  "instructions": {
    "text_instructions": [
      {
        "id": "dd2ad0f4d79b4853b8c16c72becfa002",
        "content": [
          "Data is synthetic sales orders for three customer accounts that also exist in Salesforce.\n",
          "- accounts.salesforce_account_id is the Salesforce Account Id; use it to join orders to accounts. Customer names: Acme Corp, Globex Inc, Initech.\n",
          "- Revenue means SUM(orders.order_total) for orders whose status is NOT 'Cancelled' or 'Returned', unless the user asks otherwise. Amounts are USD.\n",
          "- Line-level questions (products, quantities, discounts) use order_lines joined to orders on order_id and to products on product_id; product revenue = SUM(order_lines.net_amount).\n",
          "- Order statuses: Processing, Shipped, Delivered, Cancelled, Returned. Channels: Direct, Partner, Online.\n",
          "- Data runs from 2025-01-01 to 2026-10-25. \"This year\" means 2026; quarters are calendar quarters.\n",
          "- Always include the account name (not only the id) in results grouped by customer."
        ]
      }
    ],
    "example_question_sqls": [
      {
        "id": "5035e5a099ef4ec8add6817c1f83a9f9",
        "question": [
          "What is total revenue by customer account in 2026?"
        ],
        "sql": [
          "SELECT a.account_name, ROUND(SUM(o.order_total), 2) AS revenue_usd\n",
          "FROM skillagent.sales.orders o JOIN skillagent.sales.accounts a ON o.salesforce_account_id = a.salesforce_account_id\n",
          "WHERE o.status NOT IN ('Cancelled', 'Returned') AND YEAR(o.order_date) = 2026\n",
          "GROUP BY a.account_name ORDER BY revenue_usd DESC"
        ]
      }
    ]
  }
